"""
Independent Exact Loyalty Oracle
GrowthOS Randomized Scenario Test Environment

Validates customer point conservation, non-negativity,
cooldown periods, and merchant daily subsidy caps.

Strictly NO emojis in code, docstrings, or logs.
"""

from typing import List, Dict, Tuple, Any
from pydantic import BaseModel, Field, ConfigDict

from sim.generators.loyalty import LoyaltyGenerator, SimulatedCustomer, LoyaltyEventRecord


class LoyaltyOracleResult(BaseModel):
    """Validation report generated by ExactLoyaltyOracle."""
    model_config = ConfigDict(extra="forbid")

    passed: bool
    total_customers_checked: int
    total_points_earned: int
    total_points_redeemed: int
    total_waivers_granted: int
    total_waivers_cost_paise: int
    violations: List[str] = Field(default_factory=list)


class ExactLoyaltyOracle:
    """
    Independent ground-truth oracle for Module 1 Loyalty & Rewards.
    """

    @classmethod
    def verify(cls, loyalty_generator: LoyaltyGenerator) -> LoyaltyOracleResult:
        violations: List[str] = []
        total_earned = 0
        total_redeemed = 0
        total_waivers = 0
        total_waivers_cost = 0

        cooldown_sec = loyalty_generator.loyalty_profile.waiver_cooldown_hours * 3600
        daily_cap = loyalty_generator.loyalty_profile.daily_waiver_budget_paise

        for cust_id, cust in loyalty_generator.customers.items():
            # 1. Non-negativity invariant
            if cust.closing_points < 0:
                violations.append(
                    f"NEGATIVE_POINTS_BALANCE: Customer {cust_id} closing points is {cust.closing_points} (< 0)"
                )

            # 2. Point conservation equation: Opening + Earned - Redeemed == Closing
            expected_closing = cust.opening_points + cust.lifetime_points_earned - cust.opening_points - cust.lifetime_points_redeemed
            # Note: opening_points was already counted into lifetime_points_earned during init
            calculated_closing = cust.lifetime_points_earned - cust.lifetime_points_redeemed
            if cust.closing_points != calculated_closing:
                violations.append(
                    f"POINT_CONSERVATION_BROKEN: Customer {cust_id} closing {cust.closing_points} != calculated {calculated_closing}"
                )

            # 3. Cooldown verification between consecutive waivers
            timestamps = cust.waiver_timestamps
            for idx in range(len(timestamps) - 1):
                gap = timestamps[idx + 1] - timestamps[idx]
                if gap < cooldown_sec:
                    violations.append(
                        f"COOLDOWN_VIOLATION: Customer {cust_id} waivers at {timestamps[idx]} and {timestamps[idx+1]} gap={gap:.1f}s < required={cooldown_sec}s"
                    )

            total_earned += (cust.lifetime_points_earned - cust.opening_points)
            total_redeemed += cust.lifetime_points_redeemed
            total_waivers += cust.waiver_count
            total_waivers_cost += cust.total_waiver_savings_paise

        # 4. Merchant daily spend cap verification
        if loyalty_generator.total_waivers_spent_paise > daily_cap:
            violations.append(
                f"DAILY_BUDGET_EXCEEDED: Merchant total waiver spend {loyalty_generator.total_waivers_spent_paise} paise exceeds cap {daily_cap} paise"
            )

        if total_waivers_cost != loyalty_generator.total_waivers_spent_paise:
            violations.append(
                f"WAIVER_COST_DISCREPANCY: Sum of customer waiver savings {total_waivers_cost} != generator total {loyalty_generator.total_waivers_spent_paise}"
            )

        return LoyaltyOracleResult(
            passed=(len(violations) == 0),
            total_customers_checked=len(loyalty_generator.customers),
            total_points_earned=total_earned,
            total_points_redeemed=total_redeemed,
            total_waivers_granted=total_waivers,
            total_waivers_cost_paise=total_waivers_cost,
            violations=violations,
        )
